---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Prompt library: Saved prompts with blanks to fill in before they go to the agent.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change prompt-library.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './prompt-library.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="prompt-library" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="plb panel">
  <div class="plb-list">
    <div class="plb-h"><div class="plb-ht"><b>Prompt library</b><span class="muted">Shared with DesignMe Studio</span></div></div>
    <div class="plb-rows"></div>
  </div>
  <div class="plb-one" hidden>
    <div class="plb-h"><button class="ib plb-back" aria-label="All prompts" data-tip="All prompts"><svg class="i s"><use href="#i-chev-l"/></svg></button><div class="plb-ht"><b class="plb-tt"></b><span class="muted plb-vn"></span></div></div>
    <p class="plb-tp" aria-live="polite"></p>
    <div class="plb-vars"></div>
    <div class="plb-f"><span class="muted plb-note">Fills in as you go</span><span class="sp"></span><button class="pill primary sm plb-use">Use prompt</button></div>
  </div>
</div>
  </Fragment></div>
</div>
<script>
  import './prompt-library.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Prompt library ---------- */
/* the studio's saved prompts, each with blanks like {page}. Opening one lays its blanks out as fields, the prompt
   fills in as they change, and it can't be used until every blank has a value */
.plb{position:relative;width:100%;max-width:440px;margin:0 auto;padding:var(--dm-s-4)}
.plb-list,.plb-one{display:flex;flex-direction:column;gap:var(--dm-s-3)}
.plb-list[hidden],.plb-one[hidden]{display:none}
.plb-h{display:flex;align-items:center;gap:var(--dm-s-2);min-height:32px}
.plb-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.plb-ht b{font-weight:500;font-size:14px}
.plb-ht span{font-size:13px}
.plb-back{margin-left:-6px;flex:none}
.plb-rows{display:flex;flex-direction:column;margin:0 -8px}
.plb-row{display:flex;align-items:center;gap:var(--dm-s-3);width:100%;padding:9px var(--dm-s-2);border-radius:var(--dm-r-in);text-align:left;color:var(--dm-fg);transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.plb-row:hover{background:var(--dm-row)}}
.plb-ic{width:32px;height:32px;border-radius:calc(9px * var(--dm-rk));background:var(--dm-chip);color:var(--dm-fg2);display:grid;place-items:center;flex:none}
.plb-rt{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.plb-rt b{font-weight:500;font-size:13.5px}
.plb-rt>span{font-size:13px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.plb-n{font-size:12px;color:var(--dm-muted);flex:none}
.plb-row>svg:last-child{color:var(--dm-muted);flex:none}
.plb-tp{margin:0;padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-chip);font-size:14px;line-height:1.8;color:var(--dm-fg)}
.plb-s{padding:2px 5px;border-radius:calc(6px * var(--dm-rk));background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent));-webkit-box-decoration-break:clone;box-decoration-break:clone;transition:background .25s,color .25s,box-shadow .25s}
.plb-s.empty{background:var(--dm-surface);color:var(--dm-muted);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}
.plb-s.bad{color:var(--dm-bad);box-shadow:inset 0 0 0 1px var(--dm-bad)}
.plb-vars{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--dm-s-3)}
.plb-fd{display:flex;flex-direction:column;gap:5px;font-size:12.5px;font-weight:500;min-width:0}
.plb-fd.wide{grid-column:1/-1}
.plb-in{width:100%;border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);height:var(--dm-field-h);padding:0 var(--dm-s-3);font:inherit;font-size:13.5px;font-weight:400;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.plb-in{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.plb-in::placeholder{color:var(--dm-muted)}
.plb-in:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.plb-fd.bad .plb-in{box-shadow:inset 0 0 0 1px var(--dm-bad)}
.plb-er{font-size:12px;color:var(--dm-bad);font-weight:400}
.plb-er[hidden]{display:none}
.plb-sel{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);width:100%;height:var(--dm-field-h);padding:0 var(--dm-s-3);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font-size:13.5px;font-weight:400;color:var(--dm-fg);text-align:left;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.plb-sel{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
/* a dropdown is a field like the text field beside it: its edge steps up while it has the keyboard's focus, and opening
   its list changes nothing; it takes no ring */
.plb-sel:focus-visible{outline:0;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.plb-sel>svg{color:var(--dm-muted);flex:none;transition:transform .32s var(--dm-ease)}
.plb-sel[aria-expanded="true"]>svg{transform:rotate(180deg)}
.plb-pop{min-width:180px}
.plb-f{display:flex;align-items:center;gap:var(--dm-s-2);min-height:32px}
.plb-f .sp{flex:1}
.plb-note{font-size:13px}
.plb-done{display:flex;align-items:center;gap:var(--dm-s-3);padding:10px 10px 10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-ok-bg);font-size:13.5px}
.plb-done>svg{color:var(--dm-ok);flex:none}
.plb-done .t{flex:1;min-width:0;display:flex;flex-direction:column}
.plb-done .t span{font-size:13px}
.plb-done .t .muted{color:var(--dm-fg2)}
.plb-done .pill{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
.plb-one.used .plb-vars{opacity:.55;transition:opacity .32s}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, closePops, enter, html, swap } from '../core/core.js';
DM.def('prompt-library', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chevl}', I('chev-l'));
  const PAGE = { l:'Page', o:['Pricing v4', 'Home', 'Checkout'] };
  // the studio's saved prompts. Each blank is typed in, or picked from a short list that starts on its first option
  const P = [
    { t:'Rewrite a section', p:'Rewrite {section} on {page} so it reads {tone}.', v:{ section:{ l:'Section', ph:'Like the plan cards', er:'Say which section to rewrite' }, page:PAGE, tone:{ l:'Tone', o:['clearer', 'friendlier', 'shorter'] } } },
    { t:'Summarize feedback', p:'Summarize the comments on {page} into three fixes.', v:{ page:PAGE } },
    { t:'Check the tokens', p:'Check {page} against the {library} tokens and list what drifts.', v:{ page:PAGE, library:{ l:'Library', o:['Studio UI', 'Marketing'] } } },
    { t:'Write release notes', p:"Write release notes for {version} in the studio's voice.", v:{ version:{ l:'Version', ph:'Like Pricing v4', er:'Say which version they are for' } } }
  ];
  const cap = s => s[0].toUpperCase() + s.slice(1), uid = Math.random().toString(36).slice(2, 7);
  const list = $('.plb-list', r), one = $('.plb-one', r), rows = $('.plb-rows', r), tp = $('.plb-tp', r), vars = $('.plb-vars', r), f = $('.plb-f', r), root = $('.plb', r);
  rows.innerHTML = P.map((x, i) => `<button class="plb-row" data-i="${i}"><span class="plb-ic">${I('file-text')}</span><span class="plb-rt"><b>${x.t}</b><span>${x.p}</span></span><span class="plb-n">${Object.keys(x.v).length} ${Object.keys(x.v).length === 1 ? 'blank' : 'blanks'}</span>${I('chev-r','xs')}</button>`).join('');
  let cur = null, vals = {}, bad = new Set(), done = null;
  // the prompt as it reads now: filled blanks in the accent colour, empty ones by name, and red once they were needed
  const fill = () => { tp.innerHTML = cur.p.replace(/\{(\w+)\}/g, (m, k) => `<span class="plb-s${vals[k] ? '' : ' empty'}${bad.has(k) ? ' bad' : ''}">${vals[k] || cur.v[k].l.toLowerCase()}</span>`); };
  const err = (k, on) => { const fd = $(`.plb-fd[data-k="${k}"]`, vars), e = $('.plb-er', fd); fd.classList.toggle('bad', on); e.hidden = !on; e.textContent = on ? cur.v[k].er : ''; $('.plb-in', fd).setAttribute('aria-invalid', on); if (on) bad.add(k); else bad.delete(k); };
  function open(i){
    cur = P[i]; vals = {}; bad = new Set(); undo();
    $('.plb-tt', r).textContent = cur.t; $('.plb-vn', r).textContent = `${Object.keys(cur.v).length} ${Object.keys(cur.v).length === 1 ? 'blank' : 'blanks'}`;
    $$('.plb-pop', r).forEach(p => p.remove());
    const keys = Object.keys(cur.v), typed = keys.filter(k => !cur.v[k].o), picked = keys.filter(k => cur.v[k].o);
    // typed blanks take the full width; picked ones sit two to a row, and an odd one out takes the row. The blanks sit at
    // the foot of the card, so their lists open upward over the prompt instead of past the footer
    vars.innerHTML = [...typed, ...picked].map(k => { const v = cur.v[k], wide = !v.o || (picked.length % 2 && k === picked[picked.length - 1]);
      if (!v.o) return `<label class="plb-fd wide" data-k="${k}"><span>${v.l}</span><input class="plb-in" placeholder="${v.ph}" aria-describedby="plb-e-${k}-${uid}"><span class="plb-er" id="plb-e-${k}-${uid}" hidden></span></label>`;
      vals[k] = v.o[0];
      return `<div class="plb-fd${wide ? ' wide' : ''}" data-k="${k}"><span id="plb-l-${k}-${uid}">${v.l}</span><button class="plb-sel" aria-haspopup="menu" aria-expanded="false" aria-labelledby="plb-l-${k}-${uid} plb-v-${k}-${uid}" data-pop=".plb-pop-${k}" data-pop-pos="up"><span class="v" id="plb-v-${k}-${uid}">${cap(v.o[0])}</span>${I('chev-d','xs')}</button></div>`; }).join('');
    picked.forEach(k => {
      const pop = html(`<div class="pop plb-pop plb-pop-${k}" role="menu" aria-label="${cur.v[k].l}">${cur.v[k].o.map((o, n) => `<button class="mi" role="menuitemradio" aria-checked="${!n}" data-close data-o="${o}"><span>${cap(o)}</span><span class="ck">${I('check','xs')}</span></button>`).join('')}</div>`);
      root.appendChild(pop);
      $$('.mi', pop).forEach(m => m.addEventListener('click', () => { vals[k] = m.dataset.o; $$('.mi', pop).forEach(x => x.setAttribute('aria-checked', x === m)); swap($(`#plb-v-${k}-${uid}`, vars), cap(m.dataset.o)); fill(); }));
    });
    $$('.plb-in', vars).forEach(inp => inp.addEventListener('input', () => { const k = inp.closest('.plb-fd').dataset.k; vals[k] = inp.value.trim(); if (vals[k] && bad.has(k)) err(k, false); fill(); }));
    fill(); list.hidden = true; one.hidden = false; enter(one);
  }
  function undo(){ if (done){ done.remove(); done = null; } f.hidden = false; one.classList.remove('used'); vars.inert = false; }
  $$('.plb-row', rows).forEach(b => b.onclick = () => open(+b.dataset.i));
  $('.plb-back', r).onclick = () => { closePops(); one.hidden = true; list.hidden = false; enter(list); };
  // a prompt can't be used with a blank left empty: the blank says what it needs
  $('.plb-use', r).onclick = () => {
    const empty = Object.keys(cur.v).filter(k => !vals[k]);
    if (empty.length){ empty.forEach(k => err(k, true)); fill(); return; }
    f.hidden = true; one.classList.add('used'); vars.inert = true;
    done = html(`<div class="plb-done">${I('ok')}<span class="t">Added to your message<span class="muted">Ready to send to the agent</span></span><button class="pill sm">Undo</button></div>`);
    one.appendChild(done); enter(done); $('button', done).onclick = undo;
  };
  // the preview's story: open a prompt, try to use it with a blank empty, fill it in, pick a tone, then use it
  c.story(async s => {
    await s.beat(3); await s.tap($('.plb-row', rows)); s.away();
    await s.beat(3); await s.tap($('.plb-use', r)); s.away();
    await s.beat(4);
    const inp = $('.plb-in', vars); await s.point(inp, false);
    await s.type(inp, 'the plan cards', { n:.14, each:() => inp.dispatchEvent(new Event('input')) });
    await s.beat(1); s.away(); await s.beat(1);
    await s.tap($('.plb-sel', $('.plb-fd[data-k="tone"]', vars))); await s.beat(2);
    await s.tap($('.plb-pop-tone .mi[data-o="friendlier"]', r)); s.away(); await s.beat(3);
    await s.tap($('.plb-use', r)); s.away(); await s.beat(3);
  });
});
